const raw = $json.body ?? $json;
const headers = $json.headers ?? {};
const clean = (v, max=1000) => String(v ?? '').trim().slice(0,max);
const email = clean(raw.email,320).toLowerCase();
const name = clean(raw.name,200);
const phone = clean(raw.phone,80).replace(/[^+\d]/g,'');
const company = clean(raw.company,240);
const website = clean(raw.website,500);
const service = clean(raw.service,240);
const message = clean(raw.message,4000);
const source = clean(raw.source || 'Website',120);
const budgetNum = Number(raw.budget ?? 0);
const companySizeNum = Number(raw.company_size ?? 0);
const budget = Number.isFinite(budgetNum) && budgetNum >= 0 ? budgetNum : 0;
const company_size = Number.isFinite(companySizeNum) && companySizeNum >= 0 ? Math.round(companySizeNum) : 0;
const errors=[];
if (!name) errors.push('name is required');
if (!email) errors.push('email is required');
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email format is invalid');
if (!service) errors.push('service is required');
if (!message) errors.push('message is required');
const CONFIG = {
  mockAI: true,
  mockCRM: false,
  mockEmail: false,
  mockNotification: false,
  fromEmail: 'Automation Demo <automation@example.com>',
  salesEmail: 'sales@example.com',
  calendlyUrl: 'https://calendly.com/your-team/demo',
  twentyBaseUrl: 'http://twenty:3000',
  currencyCode: 'USD',
  processingLockMinutes: 5,
  openAiModel: 'gpt-5-mini'
};
const canonical = [email,source.toLowerCase(),service.toLowerCase(),String(budget),company.toLowerCase(),message.toLowerCase()].join('|');
let hash=2166136261;
for (let i=0;i<canonical.length;i++){ hash ^= canonical.charCodeAt(i); hash = Math.imul(hash,16777619); }
const supplied = clean(raw.request_id || headers['idempotency-key'] || headers['Idempotency-Key'],200).replace(/[^a-zA-Z0-9._:-]/g,'_');
const request_id = supplied || ('lead_' + (hash>>>0).toString(16).padStart(8,'0'));
return [{json:{request_id, validation_ok: errors.length===0, validation_errors: errors,
  received_at:new Date().toISOString(), name,email,phone,company,company_size,website,budget,service,message,source,
  config:CONFIG}}];

const lead = $('Normalize + Config').first().json;
const row = $json && $json.request_id ? $json : null;
let can_process=true, duplicate_reason='', http_code=200;
if (row) {
  if (row.status === 'completed') { can_process=false; duplicate_reason='already_completed'; http_code=200; }
  else if (row.status === 'processing') {
    const ts = Date.parse(row.received_at || '');
    const ageMin = Number.isFinite(ts) ? (Date.now()-ts)/60000 : Infinity;
    if (ageMin < Number(lead.config.processingLockMinutes || 5)) { can_process=false; duplicate_reason='already_processing'; http_code=202; }
  }
}
return [{json:{...lead,can_process,duplicate_reason,http_code,existing_state:row}}];

const lead = $('Decide Idempotency').first().json;
let score=25;
if (lead.budget>=10000) score+=35; else if (lead.budget>=5000) score+=25; else if (lead.budget>=2000) score+=15;
if (lead.company_size>=50) score+=15; else if (lead.company_size>=10) score+=8;
if (lead.email && !/(gmail|yahoo|outlook|hotmail|icloud)\./i.test(lead.email)) score+=10;
if (/automat|crm|workflow|integration|lead|sales/i.test(lead.message+' '+lead.service)) score+=15;
score=Math.min(100,score);
const category=score>=80?'HOT':score>=50?'WARM':'COLD';
const recommended_action=category==='HOT'?'schedule_demo':category==='WARM'?'request_more_info':'nurture';
return [{json:{...lead,score,category,intent:lead.service,summary:`${lead.company||lead.name} requested ${lead.service}. Budget ${lead.budget || 'not specified'}, company size ${lead.company_size || 'not specified'}.`,recommended_action,reason:`Deterministic portfolio scoring produced ${score}/100 from budget, company size, email type and buying-intent keywords.`,ai_fallback:false,ai_provider:'mock'}}];

const lead = $('Decide Idempotency').first().json;
const deterministic = () => {
  let score=25;
  if (lead.budget>=10000) score+=35; else if (lead.budget>=5000) score+=25; else if (lead.budget>=2000) score+=15;
  if (lead.company_size>=50) score+=15; else if (lead.company_size>=10) score+=8;
  if (lead.email && !/(gmail|yahoo|outlook|hotmail|icloud)\./i.test(lead.email)) score+=10;
  if (/automat|crm|workflow|integration|lead|sales/i.test(lead.message+' '+lead.service)) score+=15;
  score=Math.min(100,score); const category=score>=80?'HOT':score>=50?'WARM':'COLD';
  return {score,category,intent:lead.service,summary:`${lead.company||lead.name} requested ${lead.service}.`,recommended_action:category==='HOT'?'schedule_demo':category==='WARM'?'request_more_info':'nurture',reason:'Fallback deterministic scoring because AI response was unavailable or invalid.'};
};
let parsed=null, ai_error='';
try {
  if ($json.error) throw new Error(typeof $json.error==='string'?$json.error:JSON.stringify($json.error));
  let text = typeof $json.output_text==='string' ? $json.output_text : '';
  if (!text && Array.isArray($json.output)) {
    for (const out of $json.output) if (Array.isArray(out.content)) for (const c of out.content) if (c.type==='output_text' && typeof c.text==='string') text += c.text;
  }
  if (!text) throw new Error('OpenAI response contained no output_text');
  parsed=JSON.parse(text);
  if (!Number.isInteger(parsed.score)||parsed.score<0||parsed.score>100||!['HOT','WARM','COLD'].includes(parsed.category)) throw new Error('Structured output failed validation');
} catch(e) { ai_error=String(e.message||e); parsed=deterministic(); }
return [{json:{...lead,...parsed,ai_fallback:Boolean(ai_error),ai_error,ai_provider:ai_error?'fallback':'openai'}}];

const base=$('Qualification Context').first().json;
const httpErr=$json.error ? (typeof $json.error==='string'?$json.error:JSON.stringify($json.error)) : '';
const gqlErr=Array.isArray($json.errors)&&$json.errors.length ? JSON.stringify($json.errors) : '';
const err=httpErr||gqlErr;
if (err) return [{json:{...base,crm_search_ok:false,critical_error:'Twenty person search failed: '+err}}];
const hit=$json.data?.people?.edges?.[0]?.node || null;
return [{json:{...base,crm_search_ok:true,contact_found:Boolean(hit),contact_id:hit?.id||'',contact_action:hit?'existing':'create',crm_provider:'twenty'}}];

