const base=$('Parse Contact Search').first().json;
const err=$json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'';
const id=$json.id||$json.data?.id||$json.data?.updatePerson?.id||base.contact_id;
const deal_key='['+base.request_id+'] '+(base.company||base.name)+' — '+base.service;
return [{json:err?{...base,contact_sync_ok:false,critical_error:'Twenty person update failed: '+err}:{...base,contact_sync_ok:true,contact_id:id,contact_action:'updated',deal_key,crm_provider:'twenty'}}];

const base=$('Parse Contact Search').first().json;
const err=$json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'';
const id=$json.id||$json.data?.id||$json.data?.person?.id||$json.data?.createPerson?.id||'';
const deal_key='['+base.request_id+'] '+(base.company||base.name)+' — '+base.service;
const raw=(()=>{try{return JSON.stringify($json).slice(0,1200)}catch{return '[unserializable response]'}})();
return [{json:err||!id?{...base,contact_sync_ok:false,critical_error:'Twenty person create failed: '+(err||('missing person id; response='+raw))}:{...base,contact_sync_ok:true,contact_id:id,contact_action:'created',deal_key,crm_provider:'twenty'}}];

const base=$('HOT Lead (Twenty)?').first().json;
const httpErr=$json.error ? (typeof $json.error==='string'?$json.error:JSON.stringify($json.error)) : '';
const gqlErr=Array.isArray($json.errors)&&$json.errors.length ? JSON.stringify($json.errors) : '';
const err=httpErr||gqlErr;
if(err)return [{json:{...base,deal_search_ok:false,critical_error:'Twenty opportunity search failed: '+err}}];
const hit=$json.data?.opportunities?.edges?.[0]?.node || null;
return [{json:{...base,deal_search_ok:true,deal_found:Boolean(hit),deal_id:hit?.id||'',deal_action:hit?'existing':'create',crm_provider:'twenty'}}];

const base=$('Parse Deal Search').first().json;
const err=$json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'';
const id=$json.id||$json.data?.id||$json.data?.opportunity?.id||$json.data?.createOpportunity?.id||'';
const raw=(()=>{try{return JSON.stringify($json).slice(0,1200)}catch{return '[unserializable response]'}})();
return [{json:err||!id?{...base,deal_sync_ok:false,critical_error:'Twenty opportunity create failed: '+(err||('missing opportunity id; response='+raw))}:{...base,deal_sync_ok:true,deal_id:id,deal_action:'created',crm_provider:'twenty'}}];

const c=$json.category;
let subject,text;
if(c==='HOT'){
  subject=`Next step for ${$json.service}`;
  text=`Hi ${$json.name},\n\nThanks for reaching out about ${$json.service}. Based on the scope you shared, the fastest next step is a short discovery call.\n\nBook a time here: ${$json.config.calendlyUrl}\n\nBest regards`;
}else if(c==='WARM'){
  subject=`A few details about ${$json.service}`;
  text=`Hi ${$json.name},\n\nThanks for your request. We can help with ${$json.service}. Could you reply with your current tools, expected volume, and desired launch date?\n\nBest regards`;
}else{
  subject=`Thanks for contacting us about ${$json.service}`;
  text=`Hi ${$json.name},\n\nThanks for getting in touch. We received your request about ${$json.service} and will keep the information on file.\n\nBest regards`;
}
const esc=s=>String(s).replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
const html=text.split('\n').map(x=>x?`<p>${esc(x)}</p>`:'').join('');
return [{json:{...$json,email_subject:subject,email_text:text,email_html:html}}];

const base=$('Compose Follow-up').first().json;
if($json.email_status)return [{json:$json}];
const err=$json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'';
return [{json:{...base,email_status:err?'failed':'sent',email_error:err}}];

const base=$('Normalize Client Delivery').first().json;
if($json.notification_status)return [{json:$json}];
const err=$json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'';
return [{json:{...base,notification_status:err?'failed':'sent',notification_error:err}}];

const lead=$('Decide Idempotency').first().json;
const detail=$json.critical_error || ($json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'Unknown critical integration error');
return [{json:{...lead,status:'failed',failed_at:new Date().toISOString(),critical_error:detail}}];

const b=$json.body??$json;
const eventType=String(b.event||b.type||'').trim();
const p=b.payload??{};
const email=String(p.email||p.invitee?.email||p.contact?.email||'').trim().toLowerCase();
const name=String(p.name||p.invitee?.name||p.contact?.name||'').trim();
const start_time=p.event?.start_time||p.scheduled_event?.start_time||p.start_time||'';
const CONFIG={mockCRM:false,twentyBaseUrl:'http://twenty:3000'};
const is_booking=eventType==='invitee.created';
const valid=is_booking && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
return [{json:{event_type:eventType,is_booking,valid,email,name,start_time,received_at:new Date().toISOString(),config:CONFIG,raw:b}}];

const evt=$('Normalize Calendly Event').first().json;
const row=$json&&$json.request_id?$json:null;
return [{json:{...evt,lead_found:Boolean(row),request_id:row?.request_id||'',deal_id:row?.deal_id||'',contact_id:row?.contact_id||'',lead_status:row?.status||''}}];

const base=$('Booking Context').first().json;
if($json.deal_update_ok)return [{json:$json}];
if($json.stage_discovery_ok===false)return [{json:{...base,deal_update_ok:false,deal_update_status:'failed',deal_update_error:$json.deal_update_error||'stage discovery failed'}}];
const err=$json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'';
const id=$json.id||$json.data?.id||$json.data?.opportunity?.id||$json.data?.updateOpportunity?.id||'';
const raw=(()=>{try{return JSON.stringify($json).slice(0,1200)}catch{return '[unserializable response]'}})();
return [{json:{...base,deal_update_ok:!err&&Boolean(id),deal_update_status:err?'failed':'updated',deal_update_error:err||(!id?('missing opportunity id in response; response='+raw):''),selected_stage:$('Choose Booking Stage').first().json.selected_stage||''}}];

const base=$('Booking Context').first().json;
const httpErr=$json.error?(typeof $json.error==='string'?$json.error:JSON.stringify($json.error)):'';
const gqlErr=Array.isArray($json.errors)&&$json.errors.length?JSON.stringify($json.errors):'';
if(httpErr||gqlErr) return [{json:{...base,stage_discovery_ok:false,deal_update_error:httpErr||gqlErr}}];
const values=($json.data?.__type?.enumValues||[]).map(x=>x.name).filter(Boolean);
if(!values.length) return [{json:{...base,stage_discovery_ok:false,deal_update_error:'OpportunityStageEnum returned no values'}}];
const preferred=['MEETING','CONNECTED','TECHNICAL_EVALUATION','SCREENING','PROPOSAL','COMMITTED'];
let stage=preferred.find(x=>values.includes(x));
if(!stage) stage=values.find(x=>!['WON','LOST','CUSTOMER'].includes(x)) || values[0];
return [{json:{...base,stage_discovery_ok:true,selected_stage:stage,available_stages:values}}];

const e=$json.execution??{}; const t=$json.trigger??{}; const w=$json.workflow??{};
const msg=e.error?.message||t.error?.message||'Unknown workflow error';
return [{json:{timestamp:new Date().toISOString(),request_id:'',stage:'workflow_error',status:'failed',detail:`workflow=${w.name||w.id||'unknown'}; execution=${e.id||'n/a'}; lastNode=${e.lastNodeExecuted||'n/a'}; error=${msg}`,execution_id:String(e.id||'')}}];
